"""Release 1.72.578 HazardTools: one hunk on the LIVE inc/instruments.php (the require of inc/hazards-tools.php). Generated by make_deploy578.py."""
RELS = ['inc/instruments.php']
HUNKS = {'inc/instruments.php': [("if ( file_exists( __DIR__ . '/garden-tools.php' ) ) { require_once __DIR__ . '/garden-tools.php'; }", "if ( file_exists( __DIR__ . '/garden-tools.php' ) ) { require_once __DIR__ . '/garden-tools.php'; }\n\n/* 1.72.578 (HAD-670): the environmental-hazards map tools (hzmap, hzant, hzcompare, hzcity, hzplan); loaded only if present */\nif ( file_exists( __DIR__ . '/hazards-tools.php' ) ) { require_once __DIR__ . '/hazards-tools.php'; }", 1)]}


def apply(rel, txt):
    if rel not in HUNKS:
        raise SystemExit('ashira_578: no hunk on ' + rel)
    for old, new, n in HUNKS[rel]:
        if new in txt:
            raise SystemExit('ashira_578: the live %s already holds the new text' % rel)
        k = txt.count(old)
        if k != n:
            raise SystemExit('ashira_578: anchor x%d (want %d) in the live %s' % (k, n, rel))
        txt = txt.replace(old, new)
    return txt
